// ---- hex decode helper ------------------------------------------------------

fn hex_decode(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

// ---- v2 decryption tests ----------------------------------------------------

#[test]
fn static_v2_512_decrypts_to_known_plaintext() {
    let ct = hex_decode(V2_512_CT);
    let mut out = Vec::new();
    decrypt_stream(V2_512_PRIV_PEM, &mut ct.as_slice(), &mut out, None).unwrap();
    assert_eq!(out, PLAINTEXT);
}

