// ---- byte-layout spot checks ------------------------------------------------

#[test]
fn static_v2_512_magic_and_version_bytes_are_correct() {
    let ct = hex_decode(V2_512_CT);
    assert_eq!(&ct[0..4], b"PQFL", "magic");
    assert_eq!(ct[4], 0x02, "v2 version byte");
    assert_eq!(
        u16::from_le_bytes([ct[5], ct[6]]),
        512u16,
        "KEM_VARIANT 512"
    );
}

#[test]
fn static_v2_768_magic_and_version_bytes_are_correct() {
    let ct = hex_decode(V2_768_CT);
    assert_eq!(&ct[0..4], b"PQFL", "magic");
    assert_eq!(ct[4], 0x02, "v2 version byte");
    assert_eq!(
        u16::from_le_bytes([ct[5], ct[6]]),
        768u16,
        "KEM_VARIANT 768"
    );
}

#[test]
fn static_v2_1024_magic_and_version_bytes_are_correct() {
    let ct = hex_decode(V2_1024_CT);
    assert_eq!(&ct[0..4], b"PQFL", "magic");
    assert_eq!(ct[4], 0x02, "v2 version byte");
    assert_eq!(
        u16::from_le_bytes([ct[5], ct[6]]),
        1024u16,
        "KEM_VARIANT 1024"
    );
}

#[test]
fn static_v3_768_version_byte_and_original_size_are_correct() {
    let ct = hex_decode(V3_768_CT);
    assert_eq!(ct[4], 0x03, "v3 version byte");
    // ORIGINAL_SIZE is at offset 7 + KEM_CT_LEN_768(1088) + NONCE(12) = 1107
    let size_off = 7 + 1088 + 12;
    let original_size = u64::from_le_bytes(ct[size_off..size_off + 8].try_into().unwrap());
    assert_eq!(
        original_size,
        PLAINTEXT.len() as u64,
        "ORIGINAL_SIZE matches plaintext length"
    );
}

#[test]
fn static_v3_hybrid_variant_field_is_correct() {
    let ct = hex_decode(V3_HYBRID_CT);
    assert_eq!(ct[4], 0x03, "v3 version byte");
    // Hybrid variant = 0x0301
    assert_eq!(
        u16::from_le_bytes([ct[5], ct[6]]),
        0x0301u16,
        "KEM_VARIANT hybrid"
    );
}

#[test]
fn static_v4_768_recipient_count_is_two() {
    let ct = hex_decode(V4_768_CT);
    assert_eq!(ct[4], 0x04, "v4 version byte");
    assert_eq!(
        u16::from_le_bytes([ct[5], ct[6]]),
        2u16,
        "COUNT = 2 recipients"
    );
}
